import "@/styles/globals.css";
import React, { Suspense } from "react";
import { Comfortaa } from "next/font/google";
import Script from "next/script";
import dynamic from "next/dynamic";

import { ThemeProvider } from "@/components/theme-provider";
import Footer from "@/components/footer";
import { Metadata } from "next";
import { siteConfig } from "@/config/site";

const comfortaa = Comfortaa({ 
  subsets: ["latin"],
  display: "swap",
  preload: true,
  variable: "--font-comfortaa",
});

// Dynamic import for MenuBar to reduce initial bundle
const MenuBar = dynamic(() => import("@/components/theme-toggle"), {
  loading: () => <div className="h-12 w-48 animate-pulse bg-gold/20 rounded-full" />,
  ssr: false,
});

// Lazy load Footer
const FooterLazy = dynamic(() => import("@/components/footer"), {
  loading: () => <div className="h-24 bg-black-light animate-pulse" />,
});

export const metadata: Metadata = {
  title: {
    default: siteConfig.name,
    template: `%s - ${siteConfig.name}`,
  },
  description: siteConfig.description,
  keywords: siteConfig.keywords,
  metadataBase: new URL('https://www.hilaryokello.com'),
  openGraph: {
    title: siteConfig.name,
    description: siteConfig.description,
    type: 'website',
    locale: 'en_US',
  },
  twitter: {
    card: 'summary_large_image',
    title: siteConfig.name,
    description: siteConfig.description,
  },
  robots: {
    index: true,
    follow: true,
  },
};


export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html suppressHydrationWarning lang="en" className={comfortaa.variable}>
      <head>
        <meta charSet="utf-8" />
        <meta content="width=device-width, initial-scale=1" name="viewport" />
        <meta content="Hilary Okello's personal website" name="description" />
        <meta name="theme-color" content="#000000" />
      </head>
      <Script
        async
        src="https://www.googletagmanager.com/gtag/js?id=G-36J4TDZWT9"
        strategy="afterInteractive"
      />
    <Script id="google-analytics" strategy="afterInteractive">
  {`window.dataLayer = window.dataLayer || [];
  function gtag(){dataLayer.push(arguments);}
  gtag('js', new Date());

  gtag('config', 'G-36J4TDZWT9');`}
</Script>

      <body
        className="font-sans antialiased"
        style={{ backgroundColor: "black" }}
      >
        <ThemeProvider attribute="class" defaultTheme="dark" enableSystem={false}>
          {/* Navbar positioned on top of hero */}
          <div className="absolute top-20 left-0 right-0 z-40 flex justify-center px-4">
            <MenuBar />
          </div>

          {/* Main content with enough top padding to avoid overlap */}
          <Suspense fallback={<div className="min-h-screen bg-black" />}>
            <div className="">{children}</div>
          </Suspense>
        </ThemeProvider>
        <FooterLazy />
      </body>
    </html>
  );
}
